 import unittest
from candidate import string_sequence

class TestStringSequence(unittest.TestCase):
    def test_string_sequence_zero(self):
        self.assertEqual(string_sequence(0), '0')

    def test_string_sequence_one(self):
        self.assertEqual(string_sequence(1), '0')

    def test_string_sequence_positive(self):
        self.assertEqual(string_sequence(5), '0 1 2 3 4 5')

    def test_string_sequence_negative(self):
        self.assertEqual(string_sequence(-5), '-5 -4 -3 -2 -1 0')

    def test_string_sequence_zero_padding(self):
        self.assertEqual(string_sequence(0), '0')
        self.assertEqual(string_sequence(1), '0')
        self.assertEqual(string_sequence(2), '0 1')
        self.assertEqual(string_sequence(3), '0 1 2')
        self.assertEqual(string_sequence(4), '0 1 2 3')
        self.assertEqual(string_sequence(5), '0 1 2 3 4')

    def test_string_sequence_empty_input(self):
        self.assertIsInstance(string_sequence(-1), TypeError)
        self.assertIsInstance(string_sequence(float('inf')), TypeError)

if __name__ == '__main__':
    unittest.main()
